/**
 * Measured facts about every shipped world, by slug.
 *
 * GENERATED by `npm run courses:stats`. Do not edit by hand — run the script.
 *
 * Every number here was read off the geometry the game actually builds: the
 * part counts from the document, the route facts by solving the course and
 * walking the surfaces the solver stood on. That is the point of the file.
 * The guide pages under `/parkour/<slug>` are the site's real written
 * content, and written content about a game is worth nothing if its specifics
 * were invented — so none of these were. `course-facts.test.ts` recomputes
 * them and fails with the new value if a course is edited and this is not.
 *
 * The route is the SOLVER's route, not a human's: it walks surfaces with no
 * air control and no momentum, so it is a lower bound on the time and an
 * upper bound on what is reachable. A player will take more jumps than
 * `jumps` and will not match `steps`. What it is sound about is the shape of
 * the course — the longest gap it must cross, how far it climbs, the biggest
 * drop on the way.
 */

export interface RouteFacts {
  /** Moves along the solver's route, walks and jumps together. */
  readonly steps: number;
  /** Moves that left the ground. */
  readonly jumps: number;
  /** Empty cells across the widest gap on the route. */
  readonly longestGap: number;
  /** Tallest single step up, in cells. */
  readonly biggestRise: number;
  /** Longest single fall, in cells. */
  readonly biggestDrop: number;
  /** Every cell gained, summed — the climb if you never came back down. */
  readonly climb: number;
  /** Goal height minus spawn height. */
  readonly netRise: number;
}

export interface WorldFacts {
  readonly parts: number;
  readonly props: number;
  readonly checkpoints: number;
  readonly hazards: number;
  readonly spanX: number;
  readonly spanZ: number;
  readonly spanY: number;
  /** Absent for a world with no goal — a sandbox has no route to solve. */
  readonly route?: RouteFacts;
}

